import math
from numbers import Real


def continuous_headings(values, jump_limit=180.0):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if isinstance(jump_limit, bool) or not isinstance(jump_limit, Real):
        raise TypeError("jump_limit must be real")
    if not math.isfinite(jump_limit) or not 0 < jump_limit <= 180:
        raise ValueError("jump_limit must be in (0, 180]")
    checked = []
    for value in values:
        if isinstance(value, bool) or not isinstance(value, Real):
            raise TypeError("headings must be real")
        if not math.isfinite(value):
            raise ValueError("headings must be finite")
        checked.append(float(value))
    if not checked:
        return []
    result = [checked[0]]
    for value in checked[1:]:
        adjusted = value
        while adjusted - result[-1] > jump_limit:
            adjusted -= 180.0
        while adjusted - result[-1] < -jump_limit:
            adjusted += 180.0
        result.append(adjusted)
    return result
```

